create table public.categories (id uuid primary key default gen_random_uuid(), tenant_id uuid not null references public.tenants(id) on delete cascade, name text not null, created_at timestamptz not null default now(), unique(tenant_id,name));
create table public.suppliers (id uuid primary key default gen_random_uuid(), tenant_id uuid not null references public.tenants(id) on delete cascade, name text not null, sales_name text, whatsapp text, address text, notes text, created_at timestamptz not null default now());
create table public.products (id uuid primary key default gen_random_uuid(), tenant_id uuid not null references public.tenants(id) on delete cascade, category_id uuid references public.categories(id) on delete set null, supplier_id uuid references public.suppliers(id) on delete set null, name text not null, sku text not null, barcode text, purchase_price numeric(14,2) not null default 0, selling_price numeric(14,2) not null default 0, stock numeric(14,3) not null default 0, minimum_stock numeric(14,3) not null default 0, unit text not null default 'pcs', image_url text, active boolean not null default true, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(tenant_id,sku));
create table public.stock_movements (id uuid primary key default gen_random_uuid(), tenant_id uuid not null references public.tenants(id) on delete cascade, branch_id uuid not null references public.branches(id) on delete cascade, product_id uuid not null references public.products(id), quantity numeric(14,3) not null, movement_type text not null check (movement_type in ('IN','OUT','ADJUSTMENT','TRANSFER')), reference_type text, reference_id uuid, notes text, created_by uuid references public.profiles(id), created_at timestamptz not null default now());
create index products_tenant_idx on public.products(tenant_id); create index products_search_idx on public.products(tenant_id,name,sku,barcode); create index stock_movements_product_idx on public.stock_movements(tenant_id,product_id,created_at desc);
alter table public.categories enable row level security; alter table public.suppliers enable row level security; alter table public.products enable row level security; alter table public.stock_movements enable row level security;
create policy categories_member on public.categories for all using (public.is_tenant_member(tenant_id)) with check (public.is_tenant_member(tenant_id));
create policy suppliers_member on public.suppliers for all using (public.is_tenant_member(tenant_id)) with check (public.is_tenant_member(tenant_id));
create policy products_member on public.products for all using (public.is_tenant_member(tenant_id)) with check (public.is_tenant_member(tenant_id));
create policy stock_movements_member on public.stock_movements for all using (public.is_tenant_member(tenant_id)) with check (public.is_tenant_member(tenant_id));
